package com.renthub.review; import com.renthub.auth.AuthService; import com.renthub.user.User; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*; @RestController @RequestMapping("/api/reviews") @CrossOrigin(origins="http://localhost:5173") public class ReviewController{private final ReviewRepository repo;private final AuthService auth;public ReviewController(ReviewRepository r,AuthService a){repo=r;auth=a;} @GetMapping("/{type}/{assetId}") public List<Review> list(@PathVariable String type,@PathVariable Long assetId){return repo.findByAssetTypeAndAssetIdOrderByCreatedAtDesc(type.toUpperCase(),assetId);} @PostMapping public Review save(@RequestHeader(value="Authorization",required=false)String h,@RequestBody Map<String,Object>b){User u=auth.require(h);String t=String.valueOf(b.get("assetType")).toUpperCase();Long a=Long.valueOf(String.valueOf(b.get("assetId")));int rating=Integer.parseInt(String.valueOf(b.get("rating")));if(rating<1||rating>5)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Rating must be between 1 and 5");Review r=repo.findByUserIdAndAssetTypeAndAssetId(u.getId(),t,a).orElseGet(Review::new);r.setUserId(u.getId());r.setAssetType(t);r.setAssetId(a);r.setRating(rating);r.setComment((String)b.get("comment"));return repo.save(r);}}
